//
//  Glyph.swift
//  PawMiawNegocios
//
//  The one icon view. The web draws Lucide line icons (2 px stroke at 24);
//  screens here keep naming SF Symbols, and `Glyph` draws the Lucide icon the
//  name maps to (GlyphNames.swift, generated by scripts/lucide-icons.py), or a
//  Lucide name directly. A name with no Lucide icon falls back to the SF
//  Symbol's outline form, so nothing reads filled where the web is drawn in
//  lines. Lucide is ISC licensed (Licenses/Lucide-LICENSE.txt).
//

import SwiftUI

struct Glyph: View {
    let name: String
    var size: CGFloat = 16

    init(_ name: String, size: CGFloat = 16) {
        self.name = name
        self.size = size
    }

    var body: some View {
        if let lucide = Self.lucide(for: name) {
            Image("lucide-\(lucide)")
                .renderingMode(.template)
                .resizable()
                .scaledToFit()
                .frame(width: size, height: size)
                .accessibilityHidden(true)
        } else {
            Image(systemName: Self.outline(name))
                .font(.system(size: size * 0.86, weight: .medium))
                .frame(width: size, height: size)
                .accessibilityHidden(true)
        }
    }

    /// The Lucide icon for an SF Symbol name (".fill" ignored) or a Lucide name.
    static func lucide(for name: String) -> String? {
        if GlyphNames.lucide.contains(name) { return name }
        if let alias = GlyphNames.aliases[name] { return alias }
        var base = name
        if base.hasSuffix(".fill") { base = String(base.dropLast(5)) }
        return GlyphNames.sf[base] ?? GlyphNames.sf[name]
    }

    /// The outline form of an SF Symbol, where it has one.
    static func outline(_ name: String) -> String {
        guard name.hasSuffix(".fill") else { return name }
        let base = String(name.dropLast(5))
        return UIImage(systemName: base) != nil ? base : name
    }
}

/// A `Label` whose icon is a `Glyph` (menus, tab items, list rows).
struct GlyphLabel: View {
    let title: String
    let icon: String
    var size: CGFloat = 16

    init(_ title: String, icon: String, size: CGFloat = 16) {
        self.title = title
        self.icon = icon
        self.size = size
    }

    var body: some View {
        Label { Text(title) } icon: { Glyph(icon, size: size) }
    }
}
